def max_sum_after_operations(n, m, a, b):
    max_sum = sum(a)
    for x in b:
        current_sum = 0
        min_prefix_sum = 0
        for i in range(n):
            current_sum += a[i]
            if i >= x:
                current_sum -= a[i - x]
            max_sum = max(max_sum, sum(a) + 2 * (current_sum - min_prefix_sum))
            min_prefix_sum = min(min_prefix_sum, current_sum)
    return max_sum

def main():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        result = max_sum_after_operations(n, m, a, b)
        print(result)

if __name__ == "__main__":
    main()
